import type { BankQuestion } from "@/lib/bank";

/** Cell Structure and Cell Division (Biology (NEET)): 134 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-cell-structure-division-1","question":"The fluid mosaic model of the plasma membrane was proposed by:","options":["Singer and Nicolson","Robert Brown","Schleiden and Schwann","Rudolf Virchow"],"answer":0,"explanation":"Singer and Nicolson proposed the fluid mosaic model in 1972: proteins float in a quasi-fluid lipid bilayer. Schleiden and Schwann gave the cell theory and Virchow added 'Omnis cellula-e cellula'.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-2","question":"The cell wall of fungi is chiefly made of:","options":["Cellulose","Peptidoglycan","Chitin","Pectin"],"answer":2,"explanation":"Fungal walls are made of chitin; plant walls of cellulose (with hemicellulose, pectin and proteins); bacterial walls of peptidoglycan.","difficulty":"easy"},
  {"id":"bio-cell-structure-division-3","question":"DNA replication takes place in which phase of the cell cycle?","options":["G₁ phase","G₂ phase","S phase","M phase"],"answer":2,"explanation":"In S (synthesis) phase DNA content doubles from 2C to 4C, but the chromosome number does not change; G₁ and G₂ are growth phases and M is division.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-4","question":"Crossing over between non-sister chromatids of homologous chromosomes occurs during:","options":["Leptotene","Zygotene","Pachytene","Diplotene"],"answer":2,"explanation":"Crossing over (mediated by recombinase) takes place at pachytene, when bivalents appear as tetrads. Zygotene is pairing (synapsis) and diplotene is when the chiasmata become visible as the synaptonemal complex dissolves.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-5","question":"Which of the following cell structures is NOT bounded by a membrane?","options":["Lysosome","Golgi cisterna","Peroxisome","Ribosome"],"answer":3,"explanation":"Ribosomes are non-membranous ribonucleoprotein particles (80S in eukaryotic cytoplasm, 70S in prokaryotes, mitochondria and chloroplasts). The other three are membrane-bound.","difficulty":"moderate"},
  {"id":"bio-cell-structure-division-6","question":"Mesosomes of bacteria are formed by:","options":["Extensions of the plasma membrane","Invagination of the outer membrane","Folding of the nuclear envelope","Fusion of ribosomes with the cell wall"],"answer":0,"explanation":"Mesosomes are extensions of the plasma membrane in the form of vesicles, tubules and lamellae; they help in cell wall formation, DNA replication and distribution, respiration and secretion.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-7","question":"The splitting of the centromere followed by movement of sister chromatids to opposite poles marks:","options":["Prophase","Metaphase","Anaphase","Telophase"],"answer":2,"explanation":"Anaphase begins when each centromere splits and the two chromatids, now daughter chromosomes, move to opposite poles with centromeres leading.","difficulty":"moderate"},
  {"id":"bio-cell-structure-division-8","question":"Gas vacuoles are found in:","options":["Amoeba and other free-living protozoa","Cyanobacteria and purple and green bacteria","All Gram-negative heterotrophic soil bacteria","Mycoplasma, the smallest living cells"],"answer":1,"explanation":"Among prokaryotic inclusion bodies, gas vacuoles occur in blue-green and in purple and green photosynthetic bacteria; phosphate, cyanophycean and glycogen granules are other inclusions.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-9","question":"Cells that exit the cycle and enter an inactive stage after G₁ are said to be in:","options":["G₀ phase","S phase","Interkinesis","G₂ phase"],"answer":0,"explanation":"G₀ (quiescent) cells are metabolically active but do not proliferate unless called upon; heart cells, for instance, do not divide at all.","difficulty":"moderate"},
  {"id":"bio-cell-structure-division-10","question":"In a human cell dividing in culture every 24 hours, what fraction of the cycle is roughly spent in M phase?","options":["About 50%","About 25%","About 4%","About 12%"],"answer":2,"explanation":"NCERT: a human cell cycle of about 24 h has an M phase of about 1 h, so cell division occupies roughly 1/24 ≈ 4% of the cycle; interphase takes over 95%.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-11","question":"Terminalisation of chiasmata, disappearance of the nucleolus and assembly of the meiotic spindle characterise:","options":["Diplotene","Metaphase I","Zygotene","Diakinesis"],"answer":3,"explanation":"Diakinesis, the last substage of prophase I, shows terminalisation of chiasmata, a fully condensed chromosome set, nucleolar disappearance and nuclear envelope breakdown; it is the transition to metaphase I.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-12","question":"In the membrane of a human erythrocyte, the approximate proportions of protein and lipid are:","options":["Protein 52%, lipid 40%","Protein 20%, lipid 75%","Protein 75%, lipid 20%","Protein 40%, lipid 52%"],"answer":0,"explanation":"Chemical analysis of the erythrocyte membrane shows about 52% protein and 40% lipid (NCERT). The ratio varies between cell types, with membrane proteins being either integral or peripheral.","difficulty":"hard","source":"NEET 2019 pattern"},
  {"id":"bio-cell-structure-division-13","question":"Which of the following is NOT a part of the endomembrane system?","options":["Lysosome","Golgi complex","Peroxisome","Endoplasmic reticulum"],"answer":2,"explanation":"The endomembrane system includes the ER, Golgi complex, lysosomes and vacuoles. Mitochondria, chloroplasts and peroxisomes are excluded because their functions are not coordinated with it.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-14","question":"The three parts of a bacterial flagellum are:","options":["Axoneme, basal body, hook","Filament, central sheath, hook","Filament, hook, basal body","Basal body, doublet, radial spoke"],"answer":2,"explanation":"A bacterial flagellum has a filament, a hook and a basal body; the filament is the longest portion and projects from the cell surface. Axoneme, doublets and radial spokes belong to eukaryotic cilia and flagella.","difficulty":"hard"},
  {"id":"bio-cell-structure-division-15","question":"Which statement about mitosis is INCORRECT?","options":["It is called equational division","It restores the nucleo-cytoplasmic ratio","Haploid cells of some lower plants and social insects divide by mitosis","It occurs only in diploid cells"],"answer":3,"explanation":"Mitosis is usually restricted to diploid somatic cells in animals, but haploid cells also divide mitotically in some lower plants and social insects (male honey bees), so 'only in diploid cells' is wrong.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-16","question":"A chromosome whose centromere lies slightly away from the middle, producing one shorter and one longer arm, is called:","options":["Sub-metacentric","Metacentric","Acrocentric","Telocentric"],"answer":0,"explanation":"Sub-metacentric: centromere slightly off-centre. Metacentric: middle, equal arms; acrocentric: near one end, one very short arm; telocentric: terminal centromere.","difficulty":"hard"},
  {"id":"bio-cell-structure-division-17","question":"The liquid endosperm of coconut is multinucleate because:","options":["Cytokinesis repeatedly occurred without karyokinesis","Karyokinesis was not followed by cytokinesis","Several nuclei fused after fertilisation","Meiosis produced many haploid nuclei in one cell"],"answer":1,"explanation":"When nuclear division (karyokinesis) is not followed by cytokinesis, a multinucleate condition, the syncytium, results, as in the liquid endosperm of coconut.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-18","question":"Which of the following best distinguishes a prokaryotic 70S ribosome from a eukaryotic cytoplasmic ribosome?","options":["70S is made of 60S and 40S subunits","70S ribosomes lack RNA","70S ribosomes occur only free in the cytoplasm, never attached","70S is made of 50S and 30S subunits"],"answer":3,"explanation":"Prokaryotic ribosomes are 70S (50S + 30S); eukaryotic cytoplasmic ribosomes are 80S (60S + 40S). S is the Svedberg sedimentation coefficient, which is why the subunits do not add arithmetically.","difficulty":"hard"},
  {"id":"bio-cell-structure-division-19","question":"How many of the following statements about mitochondria are correct?\n(i) The matrix contains a single circular DNA molecule and 70S ribosomes.\n(ii) The inner membrane forms infoldings called cristae.\n(iii) Mitochondria divide by fission.\n(iv) The outer membrane forms a continuous limiting boundary of the organelle.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are NCERT facts: circular DNA, few RNAs and 70S ribosomes in the matrix; cristae on the inner membrane; a continuous outer membrane; and fission as the mode of multiplication.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-20","question":"Match the substage of prophase I with its event.\nList I: (A) Zygotene (B) Pachytene (C) Diplotene (D) Diakinesis\nList II: (1) Dissolution of synaptonemal complex, chiasmata visible (2) Terminalisation of chiasmata (3) Formation of synaptonemal complex (4) Crossing over by recombinase","options":["A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-4, B-3, C-1, D-2","A-1, B-4, C-3, D-2"],"answer":0,"explanation":"Zygotene: synapsis and synaptonemal complex; pachytene: crossing over; diplotene: complex dissolves and chiasmata appear; diakinesis: terminalisation of chiasmata.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-21","question":"Assertion (A): Lysosomes are described as suicide bags of the cell.\nReason (R): They are rich in hydrolytic enzymes capable of digesting carbohydrates, proteins, lipids and nucleic acids.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: lysosomes are Golgi-packaged vesicles of hydrolases (lipases, proteases, carbohydrases, active at acidic pH) which, if released, digest the cell's own contents.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-22","question":"How many of the following statements about the Golgi apparatus are correct?\n(i) Cisternae are 0.5 to 1.0 μm in diameter and stacked parallel to each other.\n(ii) The convex cis face is the forming face and the concave trans face is the maturing face.\n(iii) It is the site of formation of glycoproteins and glycolipids.\n(iv) It packages hydrolytic enzymes into lysosomes.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four statements are NCERT facts about the Golgi complex: cisternal size and stacking, the cis/trans faces, glycosylation and lysosome formation.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-23","question":"Which statement about the plant cell wall is INCORRECT?","options":["The secondary wall is formed on the outer side of the primary wall","The middle lamella is made mainly of calcium pectate","The primary wall is capable of growth and diminishes as the cell matures","Plasmodesmata connect the cytoplasm of neighbouring cells"],"answer":0,"explanation":"The secondary wall is laid down on the inner side of the primary wall, towards the plasma membrane. The other three statements are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-24","question":"How many of the following are present in a prokaryotic cell: mesosome, nuclear envelope, ribosome, plasmid, endoplasmic reticulum?","options":["Only 2","Only 3","Only 4","All 5"],"answer":1,"explanation":"Prokaryotes have mesosomes, 70S ribosomes and plasmids but lack a nuclear envelope and all membrane-bound organelles including the ER. So three of five.","difficulty":"very-hard"},
  {"id":"bio-cell-structure-division-25","question":"In an organism with 2n = 16, the number of chromatids per cell at metaphase II of meiosis is:","options":["8","16","32","4"],"answer":1,"explanation":"Meiosis I halves the chromosome number to n = 8, but each chromosome still has two sister chromatids until anaphase II. So metaphase II shows 8 chromosomes = 16 chromatids. (At metaphase I it would be 16 chromosomes = 32 chromatids.)","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-26","question":"Which of the following correctly pairs the structure with its microtubule arrangement?","options":["Centriole: 9 + 2 doublets; axoneme: 9 + 0 triplets","Centriole: 9 + 2 triplets; axoneme: 9 + 0 doublets","Centriole: 9 + 0 triplets; axoneme: 9 + 2 doublets","Both centriole and axoneme: 9 + 2 doublets"],"answer":2,"explanation":"A centriole has nine peripheral triplet fibrils around a central hub (cartwheel, 9 + 0). The axoneme of cilia and flagella has nine peripheral doublets and one central pair (9 + 2).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-27","question":"Assertion (A): Metaphase is the best stage to study the morphology of chromosomes.\nReason (R): Complete disintegration of the nuclear envelope marks the start of metaphase and the chromosomes are then most condensed.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: by metaphase the envelope has gone, the chromosomes are fully condensed and spread on the metaphase plate, so their morphology is clearest.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-28","question":"How many of the following statements about meiosis are correct?\n(i) Homologous chromosomes separate in anaphase I while sister chromatids remain attached.\n(ii) Meiosis II is an equational division.\n(iii) Interkinesis is usually short-lived.\n(iv) Meiosis II resembles a normal mitosis.","options":["Only 1","Only 2","Only 3","All 4"],"answer":3,"explanation":"All four are correct. Homologues separate in anaphase I, meiosis II is equational and resembles a normal mitosis, and interkinesis is generally short-lived with no DNA replication.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-29","question":"Which statement about the nucleus is INCORRECT?","options":["The perinuclear space between the two nuclear membranes is 10 to 50 nm wide","Nuclear pores allow movement of RNA and proteins in both directions","The nucleolus is bounded by a single membrane and synthesises rRNA","Chromatin contains DNA, histones, non-histone proteins and RNA"],"answer":2,"explanation":"The nucleolus is NOT membrane-bound; it is a spherical structure in the nucleoplasm where ribosomal RNA is actively synthesised. The other three statements are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-30","question":"Match the cell or organelle with the correct size.\nList I: (A) Mycoplasma (B) Typical bacterium (C) Chloroplast length (D) Human red blood cell\nList II: (1) 7.0 μm (2) 5 to 10 μm (3) 0.3 μm (4) 1 to 2 μm","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1"],"answer":0,"explanation":"Mycoplasma, the smallest cell, is about 0.3 μm; bacteria 1 to 2 μm; a chloroplast is 5 to 10 μm long and 2 to 4 μm wide; a human RBC is about 7.0 μm in diameter.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-31","question":"Rudolf Virchow (1855) modified the cell theory by stating that:","options":["All plants and animals are composed of cells and their products","Cells arise only from pre-existing cells: Omnis cellula-e cellula","Cells can arise spontaneously from non-living matter inside the body","Every living cell must contain a nucleus and a cell wall"],"answer":1,"explanation":"Schleiden and Schwann proposed the cell theory but did not explain how new cells form; Virchow added that new cells arise from pre-existing cells.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-32","question":"The ribosomes found in the stroma of chloroplasts are:","options":["90S, larger than cytoplasmic ribosomes","80S, the same as cytoplasmic ribosomes","Absent; chloroplasts have no ribosomes","70S, smaller than cytoplasmic 80S ones"],"answer":3,"explanation":"The chloroplast stroma contains small, double-stranded circular DNA and 70S ribosomes, which are smaller than the 80S cytoplasmic ribosomes of eukaryotes.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-33","question":"Besides packaging materials, the Golgi apparatus is the important site of formation of:","options":["Steroid hormones only","Ribosomal RNA","ATP by oxidative phosphorylation","Glycoproteins and glycolipids"],"answer":3,"explanation":"Proteins synthesised on the RER are modified in the Golgi cisternae, which is the important site of formation of glycoproteins and glycolipids.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-34","question":"In plant cells, cytokinesis takes place by:","options":["A cell plate growing from the centre towards the lateral walls","A furrow in the plasma membrane deepening from the periphery inwards","Constriction of the cell wall pinched in from outside","Budding off of a daughter cell from the parent"],"answer":0,"explanation":"Plant cells are enclosed by a rigid wall, so a cell plate (the future middle lamella) forms in the centre and grows outwards. Furrowing occurs in animal cells.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-35","question":"In animal cells, lipid-like steroidal hormones are synthesised in the:","options":["Smooth endoplasmic reticulum","Ribosomes of the cytosol","Rough endoplasmic reticulum","Peroxisomes of the cytoplasm"],"answer":0,"explanation":"The SER is the major site of lipid synthesis; in animal cells steroidal hormones are made there. The RER, bearing ribosomes, is active in protein synthesis and secretion.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-36","question":"Some chromosomes have non-staining secondary constrictions at a constant location, which give the appearance of a small fragment. This fragment is called the:","options":["Chromomere","Kinetochore","Centromere","Satellite"],"answer":3,"explanation":"A satellite is the small fragment seen beyond a secondary constriction. The kinetochore is a disc-shaped structure on the sides of the centromere (primary constriction).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-37","question":"A cell in G₁ has a DNA content of 2C. What is the DNA content of one cell at metaphase II of meiosis?","options":["2C","4C","8C","C"],"answer":0,"explanation":"DNA doubles in S phase (4C); meiosis I separates homologues, so each daughter cell has 2C (two chromatids per chromosome) at metaphase II. Gametes formed after meiosis II have C.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-38","question":"In the axoneme of a cilium or flagellum, the radial spokes connect:","options":["The two central singlet microtubules to each other","Each peripheral doublet to the central sheath","The basal body to the plasma membrane of the cell","Each peripheral doublet to its neighbouring doublet"],"answer":1,"explanation":"The central tubules are joined by bridges and enclosed by a central sheath, which is linked to one tubule of each peripheral doublet by a radial spoke; peripheral doublets are joined to each other by linkers.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-39","question":"How many of the following statements about plastids are correct?\n(i) Chromoplasts contain fat-soluble carotenoid pigments such as carotene and xanthophylls.\n(ii) Amyloplasts store starch, as in potato.\n(iii) Elaioplasts store oils and fats, while aleuroplasts store proteins.\n(iv) The number of chloroplasts varies from one per cell in Chlamydomonas to 20–40 per cell in the mesophyll.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Leucoplasts are colourless plastids of varied shapes and sizes that store nutrients.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-40","question":"Match the stage of mitosis with its event.\nList I: (A) Prophase (B) Metaphase (C) Anaphase (D) Telophase\nList II: (1) Chromosomes cluster at opposite poles and the nuclear envelope reassembles (2) Chromosomal material condenses and the centrosomes move to opposite poles (3) Chromosomes align at the equatorial plate with spindle fibres attached to their kinetochores (4) Centromeres split and chromatids move to opposite poles","options":["A-2, B-4, C-3, D-1","A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4"],"answer":2,"explanation":"Condensation and centrosome movement mark prophase, alignment at the metaphase plate marks metaphase, splitting of centromeres marks anaphase, and re-formation of the nuclear envelope, nucleolus, Golgi and ER marks telophase.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-41","question":"Assertion (A): The plasma membrane is quasi-fluid in nature.\nReason (R): The lipid bilayer is held rigidly, so proteins cannot move laterally within it.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true but R is false: the quasi-fluid nature of the lipid lets proteins move laterally within the bilayer, which is important for cell growth, intercellular junctions, secretion, endocytosis and cell division.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-42","question":"How many of the following statements about the cell cycle are correct?\n(i) Interphase lasts less than 5% of the duration of the cell cycle.\n(ii) During S phase, the amount of DNA per cell doubles and the chromosome number also doubles.\n(iii) In animal cells, the centriole duplicates in the cytoplasm during G₁ phase.\n(iv) During G₂ phase, proteins are synthesised in preparation for mitosis while cell growth continues.","options":["Only 1","Only 2","Only 3","All 4"],"answer":0,"explanation":"Only (iv) is correct. Interphase lasts more than 95% of the cycle (M phase is the short one); DNA doubles in S phase but chromosome number stays 2n; and the centriole duplicates during S phase, not G₁.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-43","question":"In an organism with 2n = 20, how many chromosomes (counted by centromeres) are present in a cell at anaphase of mitosis and in a cell at anaphase I of meiosis respectively?","options":["40 and 10","20 and 20","20 and 40","40 and 20"],"answer":3,"explanation":"At mitotic anaphase sister chromatids separate, so each becomes a chromosome: 40. At anaphase I homologues separate but sister chromatids stay joined, so the cell still has 20 centromeres.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-44","question":"Which of the following is NOT a significance of mitosis?","options":["It results in growth of multicellular organisms","It restores the nucleo-cytoplasmic ratio","It helps in cell repair, as in the upper layer of the epidermis and the lining of the gut","It increases genetic variability in the population"],"answer":3,"explanation":"Mitosis produces genetically identical diploid daughter cells. Increase in genetic variability is a significance of meiosis, through crossing over and independent assortment.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-45","question":"How many of the following statements are correct?\n(i) Ribosomes were first observed under the electron microscope as dense particles by George Palade in 1953.\n(ii) Ribosomes are bounded by a single membrane.\n(iii) The cytoskeleton, made of microtubules, microfilaments and intermediate filaments, is involved in mechanical support, motility and maintenance of cell shape.\n(iv) The 'S' in 70S is a direct measure of the mass of the ribosome.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (iii) are correct. Ribosomes are non-membranous, and S (Svedberg unit) is a sedimentation coefficient that indirectly reflects density and size.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-46","question":"The first person to see and describe a live cell was:","options":["Robert Hooke","Anton von Leeuwenhoek","Robert Brown","Matthias J. Schleiden"],"answer":1,"explanation":"Anton von Leeuwenhoek first saw and described a live cell. Robert Hooke described dead cork cells, and Robert Brown later discovered the nucleus.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-47","question":"In animal cells, the centrosome usually contains:","options":["A single centriole surrounded by a dense nucleolus","Two centrioles lying perpendicular to each other","Four centrioles arranged parallel in a ring","Two basal bodies lying parallel to each other"],"answer":1,"explanation":"The centrosome is an organelle usually containing two cylindrical centrioles surrounded by amorphous pericentriolar material; the two centrioles lie perpendicular to each other.","difficulty":"easy","source":"NEET pattern"},
  {"id": "bio-cell-structure-division-48", "question": "In some bacteria, small bristle-like fibres sprouting out of the cell that help them attach to rocks in streams and to host tissues are called:", "options": ["Pili", "Flagella", "Fimbriae", "Mesosomes"], "answer": 2, "explanation": "Fimbriae are small bristle-like fibres that help some bacteria attach to rocks and host tissues. Pili are elongated tubular structures made of a special protein, and flagella are for motility.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id":"bio-cell-structure-division-49","question":"Disc-shaped structures on the sides of the centromere, to which spindle fibres attach during cell division, are called:","options":["Kinetochores","Chiasmata","Satellite bodies","Telomeres"],"answer":0,"explanation":"Every chromosome has a primary constriction, the centromere, on whose sides are disc-shaped kinetochores; the spindle fibres attach to them. Chiasmata are sites of crossing over seen in diplotene.","difficulty":"moderate","source":"NEET pattern"},
  {"id": "bio-cell-structure-division-50", "question": "Several ribosomes attached to a single mRNA, forming a chain that translates the mRNA, are called:", "options": ["Polysome", "Mesosome", "Microsome", "Nucleosome"], "answer": 0, "explanation": "Several ribosomes may attach to a single mRNA to form a polyribosome or polysome, which translates the mRNA into proteins. A nucleosome is DNA wrapped on a histone octamer.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id":"bio-cell-structure-division-51","question":"Interkinesis, the stage between meiosis I and meiosis II, is characterised by:","options":["Replication of DNA in a long S phase","A short stage with no DNA replication","Pairing of homologous chromosomes","Formation of the synaptonemal complex"],"answer":1,"explanation":"Interkinesis is generally short-lived and, unlike interphase, has no DNA replication; it is followed by prophase II, which is much simpler than prophase I.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-52","question":"Bacteria are classified as Gram-positive or Gram-negative on the basis of:","options":["The presence or absence of a true nucleus","The type of ribosomes (70S or 80S) that they carry","Their cell envelope and response to Gram staining","Whether they bear flagella, pili or fimbriae"],"answer":2,"explanation":"Based on differences in the cell envelope and their response to Gram staining, bacteria that take up the stain are Gram positive and those that do not are Gram negative.","difficulty":"moderate","source":"NEET pattern"},
  {"id": "bio-cell-structure-division-53", "question": "The number of chloroplasts per cell varies from one per cell in ______ to ______ per cell in the mesophyll of leaves.", "options": ["Spirogyra; 5–10", "Chlamydomonas; 20–40", "Chlamydomonas; 100–200", "Volvox; 2–4"], "answer": 1, "explanation": "NCERT gives the range as 1 chloroplast per cell in the green alga Chlamydomonas to 20–40 per cell in leaf mesophyll. The other ranges are invented.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-cell-structure-division-54","question":"Which statement about the plant vacuole is correct?","options":["It is bounded by a double membrane, the tonoplast, like a plastid","It can fill up to 90% of the cell; its tonoplast pumps ions in uphill","Its ion concentration stays lower than the cytoplasm, so water leaves","It mainly stores hydrolytic enzymes that are active at alkaline pH"],"answer":1,"explanation":"The vacuole is bounded by a single membrane, the tonoplast, and can occupy up to 90% of a plant cell's volume. The tonoplast moves ions into the vacuole against the gradient, so their concentration in the vacuole is significantly higher than in the cytoplasm.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-cell-structure-division-55", "question": "In the oocytes of some vertebrates, which substage of prophase I can last for months or even years?", "options": ["Leptotene", "Zygotene", "Pachytene", "Diplotene"], "answer": 3, "explanation": "NCERT notes that diplotene can last for months or years in the oocytes of some vertebrates. Pachytene is the stage of crossing over, and leptotene and zygotene are short.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-cell-structure-division-56","question":"The endoplasmic reticulum divides the intracellular space into two compartments. These are:","options":["Luminal (inside the ER) and extra luminal","Cis (forming) and trans (maturing) faces","Inner matrix and outer intermembrane space","Stroma and thylakoid lumen compartments"],"answer":0,"explanation":"The ER divides the intracellular space into a luminal compartment (inside the ER) and an extra luminal compartment (the cytoplasm). Cis and trans are faces of the Golgi; matrix and intermembrane space belong to mitochondria.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-57","question":"Many membrane-bound minute vesicles containing various enzymes, called microbodies, are present in:","options":["Only plant cells, as glyoxysomes","Only animal cells, as peroxisomes","Both plant and animal cells","Only prokaryotic cells"],"answer":2,"explanation":"Microbodies, minute membrane-bound vesicles containing various enzymes, are present in both plant and animal cells. Prokaryotes lack membrane-bound organelles.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-cell-structure-division-58", "question": "The hydrolytic enzymes of lysosomes (lipases, proteases, carbohydrases) are optimally active at:", "options": ["Acidic pH", "Neutral pH", "Alkaline pH", "Any pH between 2 and 12"], "answer": 0, "explanation": "Lysosomal enzymes are optimally active at acidic pH. This is a frequent trap because many digestive enzymes of the small intestine work at alkaline pH.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-59", "question": "In animal cells, which event occurs in the cytoplasm during the S phase of the cell cycle?", "options": ["Formation of the spindle", "Duplication of the centriole", "Breakdown of the nuclear envelope", "Formation of the cell plate"], "answer": 1, "explanation": "While DNA replicates in the nucleus during S phase, the centriole duplicates in the cytoplasm of animal cells. Spindle formation and envelope breakdown are events of M phase.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-60", "question": "How many of the following statements about transport across the plasma membrane are correct?\n(i) Neutral solutes may move across the membrane by simple diffusion along the concentration gradient.\n(ii) Water moves across the membrane by diffusion, a process called osmosis.\n(iii) Polar molecules cannot pass through the non-polar lipid bilayer and need a carrier protein.\n(iv) The Na⁺/K⁺ pump moves ions against the concentration gradient using ATP.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Passive transport covers simple diffusion of neutral solutes and osmosis of water; polar molecules need carrier proteins, and active transport such as the Na⁺/K⁺ pump uses ATP to move ions against the gradient.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-61", "question": "Match the prokaryotic structure with its role.\nList I: (A) Pili (B) Plasmid (C) Mesosome (D) Glycocalyx\nList II: (1) Small circular extra-chromosomal DNA that may confer antibiotic resistance (2) Outer layer that may be a loose slime layer or a thick capsule (3) Elongated tubular structures made of a special protein (4) Infolding of the plasma membrane that helps in respiration, secretion and DNA distribution", "options": ["A-3, B-1, C-4, D-2", "A-1, B-3, C-2, D-4", "A-3, B-4, C-1, D-2", "A-2, B-1, C-4, D-3"], "answer": 0, "explanation": "Pili are tubular protein structures; plasmids are small circular DNA conferring traits such as antibiotic resistance; mesosomes are membrane infoldings aiding respiration, secretion and DNA distribution; the glycocalyx is a loose slime layer or a tough capsule.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-62", "question": "Assertion (A): Cells in the G₀ phase do not divide under normal conditions.\nReason (R): Cells in G₀ are metabolically inactive and can never be called back into the cell cycle.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: G₀ cells, such as many heart cells, do not proliferate. R is false: NCERT says G₀ cells remain metabolically active and can proliferate if called on to do so depending on the requirement of the organism.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-cell-structure-division-63","question":"How many of the following statements about the cell cycle are correct?\n(i) G₁ is the interval between mitosis and the initiation of DNA replication.\n(ii) If a cell has 2n chromosomes in G₁, it still has 2n chromosomes after S phase.\n(iii) In G₂, proteins are synthesised in preparation for mitosis while cell growth continues.\n(iv) In animal cells the centriole duplicates during G₂.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. DNA doubles in S phase but the chromosome number does not change. Statement (iv) is wrong: the centriole duplicates in the cytoplasm during S phase, not G₂.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-cell-structure-division-64", "question": "A plant has 2n = 24. The number of bivalents at pachytene, the number of chromatids at metaphase I, and the number of chromosomes in each nucleus at telophase II are respectively:", "options": ["24, 48, 24", "12, 24, 12", "12, 48, 12", "12, 48, 24"], "answer": 2, "explanation": "24 chromosomes pair into 12 bivalents. Each chromosome has two chromatids after S phase, so metaphase I has 24 × 2 = 48 chromatids. After meiosis II each nucleus has n = 12 chromosomes.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-65", "question": "Arrange the following events of prophase I of meiosis in the correct order:\n(i) Dissolution of the synaptonemal complex\n(ii) Appearance of recombination nodules\n(iii) Synapsis of homologous chromosomes\n(iv) Terminalisation of chiasmata", "options": ["(iii), (ii), (i), (iv)", "(ii), (iii), (iv), (i)", "(iii), (i), (ii), (iv)", "(i), (iii), (ii), (iv)"], "answer": 0, "explanation": "Synapsis occurs in zygotene, recombination nodules appear in pachytene, the synaptonemal complex dissolves in diplotene, and chiasmata terminalise in diakinesis.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-66", "question": "Match the cell part with its description.\nList I: (A) Tonoplast (B) Nucleolus (C) Trans face of Golgi (D) Polysome\nList II: (1) Site of active ribosomal RNA synthesis (2) Membrane surrounding the vacuole (3) Several ribosomes on one mRNA (4) Maturing face of the Golgi apparatus", "options": ["A-2, B-4, C-1, D-3", "A-2, B-1, C-4, D-3", "A-3, B-1, C-4, D-2", "A-4, B-1, C-2, D-3"], "answer": 1, "explanation": "The tonoplast surrounds the vacuole, the nucleolus is the site of active rRNA synthesis, the trans face is the maturing face of the Golgi, and a polysome is several ribosomes on one mRNA.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-cell-structure-division-67", "question": "Assertion (A): Plant cells undergo cytokinesis by forming a cell plate rather than by a cleavage furrow.\nReason (R): Plant cells are enclosed by a relatively inextensible cell wall.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Because the wall cannot be pinched in, new wall formation begins in the centre as a cell plate and grows outward to meet the existing lateral walls.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-cell-structure-division-68","question":"How many of the following statements about chromosomes are correct?\n(i) A human somatic cell has 46 chromosomes.\n(ii) Every chromosome has a primary constriction, the centromere.\n(iii) An acrocentric chromosome has its centromere at the terminal end.\n(iv) At metaphase each chromosome consists of two sister chromatids held together by the centromere.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"Statements (i), (ii) and (iv) are correct. Statement (iii) describes a telocentric chromosome; an acrocentric chromosome has its centromere close to the end, giving one extremely short and one very long arm.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-69","question":"Which pair of cell type and shape is INCORRECTLY matched?","options":["Red blood cell — round and biconcave","White blood cell — amoeboid","Nerve cell — branched and long","Mesophyll cell — columnar, ciliated"],"answer":3,"explanation":"NCERT shows RBCs as round and biconcave, WBCs as amoeboid and nerve cells as branched and long. Mesophyll cells are round or oval, not columnar and ciliated, so this pair is wrong.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-cell-structure-division-70", "question": "Which statement about mitochondria and chloroplasts is INCORRECT?", "options": ["Both are double-membrane-bound organelles", "Both contain their own small circular DNA", "Both have 70S ribosomes in their matrix or stroma", "Both arise only from the Golgi apparatus"], "answer": 3, "explanation": "Mitochondria and chloroplasts are double-membrane-bound, contain circular DNA and 70S ribosomes, and divide by fission. They do not arise from the Golgi, which is the incorrect statement.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-cell-structure-division-71","question":"Normal mature erythrocytes of many mammals and the sieve tube cells of vascular plants lack a:","options":["Plasma membrane","Cytoplasm","Nucleus","Lipid bilayer"],"answer":2,"explanation":"These cells lose their nucleus as they mature but keep their plasma membrane and cytoplasm.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-72","question":"In Amoeba, the contractile vacuole is important for:","options":["Excretion and osmoregulation","Digestion of engulfed food particles","Locomotion by pseudopodia","Storage of reserve food"],"answer":0,"explanation":"The contractile vacuole removes excess water and wastes. Food vacuoles, formed by engulfing food particles, carry out digestion.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-73","question":"Yeast can progress through the cell cycle in only about:","options":["24 hours","12 hours","10 minutes","90 minutes"],"answer":3,"explanation":"A yeast cell completes a cell cycle in about 90 minutes, whereas a typical human cell in culture takes about 24 hours.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-74","question":"The material of the nucleus that stains with basic dyes was named chromatin by:","options":["Robert Brown","George Palade","Camillo Golgi","Flemming"],"answer":3,"explanation":"Flemming coined the term chromatin. Robert Brown discovered the nucleus, Golgi described the Golgi apparatus, and Palade first saw ribosomes.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-75","question":"Schwann (1839), from his studies on plant tissues, concluded that a unique character of plant cells is the presence of the:","options":["Cell wall","Nucleus","Vacuole","Mitochondria"],"answer":0,"explanation":"Schwann reported that cells have a thin outer layer, now called the plasma membrane, and that the cell wall is unique to plant cells.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-76","question":"During the G2 phase of the cell cycle:","options":["DNA is replicated and doubles from 2C to 4C","The cell exits the cycle and becomes quiescent (G0)","Proteins for mitosis are made as growth continues","Sister chromatids separate towards the poles"],"answer":2,"explanation":"In G2, proteins needed for mitosis are made and the cell keeps growing. DNA replication happens in S phase, quiescence is G0, and chromatids separate at anaphase.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-77","question":"In plants, mitotic divisions that allow continuous growth throughout life occur in the:","options":["Mature xylem vessels and tracheids","Sieve tubes of the phloem","Cork cells of the bark","Apical and lateral meristems"],"answer":3,"explanation":"Mitosis in apical and lateral meristems lets plants grow throughout their life. Mature xylem vessels and cork cells are dead, and sieve tubes have no nucleus.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-78","question":"Which of the following is NOT a function of the plant cell wall?","options":["Giving shape to the cell","Protecting the cell from mechanical damage and infection","Helping in cell-to-cell interaction","Synthesising proteins"],"answer":3,"explanation":"The cell wall gives shape, protects the cell, helps in cell-to-cell interaction and keeps out undesirable macromolecules. Proteins are synthesised by ribosomes.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-79","question":"Larger and more numerous nucleoli are present in cells that are:","options":["Actively synthesising proteins","In the G0 (quiescent) stage","Dead, such as cork cells","Mature mammalian red blood cells"],"answer":0,"explanation":"The nucleolus is the site of active ribosomal RNA synthesis, so cells making a lot of protein have larger and more numerous nucleoli.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-80","question":"In some prokaryotes such as cyanobacteria, membranous extensions into the cytoplasm that contain pigments are called:","options":["Mesosomes","Gas vacuoles","Chromatophores","Cyanophycean granules"],"answer":2,"explanation":"Chromatophores are membranous extensions carrying photosynthetic pigments. Mesosomes are infoldings involved in wall formation, DNA distribution and respiration, while gas vacuoles and cyanophycean granules are inclusion bodies, not pigment-bearing membranes.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-81","question":"Phosphate granules, cyanophycean granules and glycogen granules in prokaryotic cells are:","options":["Membrane-bound storage vacuoles of the cell","Small circular DNA molecules called plasmids","Infolded parts of the mesosome membrane","Inclusion bodies, not bound by any membrane"],"answer":3,"explanation":"Reserve material in prokaryotes is stored as inclusion bodies, which have no membrane and lie free in the cytoplasm.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-82","question":"The cell wall of algae is made of:","options":["Chitin, peptidoglycan and lipopolysaccharide","Cellulose, hemicellulose, pectins and proteins only","Murein (peptidoglycan) with teichoic acids","Cellulose, galactans, mannans and calcium carbonate"],"answer":3,"explanation":"Algal cell walls contain cellulose, galactans, mannans and minerals such as calcium carbonate. Other plants have walls of cellulose, hemicellulose, pectins and proteins.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-83","question":"A typical mitochondrion is sausage-shaped or cylindrical, with a:","options":["Width of 0.2–1.0 µm and length of 1.0–4.1 µm","Width of 2–4 µm and length of 5–10 µm","Width of 15–20 nm and length of 25–30 nm","Width of 0.5–1.0 mm and length of 2.0–4.1 mm"],"answer":0,"explanation":"Mitochondria are 0.2 to 1.0 µm wide (about 0.5 µm on average) and 1.0 to 4.1 µm long. A width of 2 to 4 µm and length of 5 to 10 µm describes a chloroplast, and the millimetre option is a unit trap.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-84","question":"The size of a prokaryotic 70S ribosome, made of 50S and 30S subunits, is about:","options":["15 nm by 20 nm","0.5 µm by 1 µm","2 µm by 4 µm","150 nm by 200 nm"],"answer":0,"explanation":"Prokaryotic ribosomes measure about 15 nm by 20 nm, far too small to be seen under a light microscope.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-85","question":"At telophase I of meiosis, the nuclear membrane and nucleolus reappear and cytokinesis follows. The result is a:","options":["Tetrad of cells","Bivalent","Syncytium","Dyad of cells"],"answer":3,"explanation":"Telophase I with cytokinesis gives a dyad of cells; meiosis II then gives a tetrad. A bivalent is a pair of synapsed homologous chromosomes.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-86","question":"Which statement about meiosis II is correct?","options":["It is preceded by a fresh round of DNA replication during interkinesis","Homologous chromosomes pair up again during its prophase","It begins just after cytokinesis, before chromosomes fully elongate","Crossing over takes place again during its prophase"],"answer":2,"explanation":"Meiosis II starts right after cytokinesis and resembles a normal mitosis. Interkinesis has no DNA replication, and pairing and crossing over happen only in prophase I.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-87","question":"A cell in G1 has 14 chromosomes and a DNA content of 2C. After the S phase, in G2, it will have:","options":["28 chromosomes and 4C DNA","14 chromosomes and 4C DNA","14 chromosomes and 2C DNA","28 chromosomes and 2C DNA"],"answer":1,"explanation":"DNA doubles in S phase, but each chromosome now has two sister chromatids joined at one centromere, so the chromosome number stays 14.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-88","question":"In an animal cell, the centrosome, which was duplicated during interphase, begins to move towards the opposite poles of the cell during:","options":["Prophase","Metaphase","Anaphase","Telophase"],"answer":0,"explanation":"In prophase the two centrosomes move to opposite poles, each radiating asters, and together with the spindle fibres they form the mitotic apparatus.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-89","question":"At the end of mitotic prophase, a cell viewed under the microscope no longer shows the:","options":["Condensed chromosomes, centrosomes and spindle fibres","Centrosomes, chromosomes and the plasma membrane","Golgi, ER, nucleolus and nuclear envelope","Plasma membrane, mitochondria and spindle"],"answer":2,"explanation":"By the end of prophase the Golgi complexes, ER, nucleolus and nuclear envelope have disappeared from view, while the condensed chromosomes become clearer.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-90","question":"From the following list, how many are functions of mesosomes?\nCell wall formation; DNA replication and distribution to daughter cells; respiration; secretion; increasing the surface area and enzymatic content of the plasma membrane; storage of photosynthetic pigments; attachment to host tissues","options":["Three","Four","Five","Six"],"answer":2,"explanation":"The first five are functions of mesosomes. Pigments are held in chromatophores, and attachment to rocks or host tissues is the job of fimbriae.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-91","question":"An organism has 2n = 8. How many chromosomes (counted by centromeres) are present in each cell at anaphase II of meiosis?","options":["4","8","16","2"],"answer":1,"explanation":"After meiosis I each cell has 4 chromosomes, each with two chromatids. At anaphase II the centromeres split, so each cell briefly has 8 chromosomes, 4 moving to each pole.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-92","question":"A single cell divides by mitosis, and all its daughter cells keep dividing synchronously until there are 64 cells. How many generations of division, and how many individual mitotic divisions in total, have taken place?","options":["6 and 64","6 and 63","64 and 63","32 and 6"],"answer":1,"explanation":"2 to the power 6 = 64, so there are six generations. The total number of divisions is 1 + 2 + 4 + 8 + 16 + 32 = 63, since each division adds one cell.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-93","question":"If every product of meiosis is functional, how many diploid meiocytes must undergo meiosis to form 100 haploid cells?","options":["100","50","25","200"],"answer":2,"explanation":"Each meiocyte gives four haploid cells after meiosis I and II, so 100 / 4 = 25 meiocytes are needed.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-94","question":"From the following list, how many are present in plant cells but absent from animal cells?\nCell wall, plastids, large central vacuole, centrioles, Golgi apparatus, mitochondria","options":["Exactly 2","Exactly 4","Exactly 3","Exactly 5"],"answer":2,"explanation":"Cell wall, plastids and a large central vacuole are found in plant cells but not in animal cells. Centrioles are found in animal cells and are absent in almost all plant cells; Golgi and mitochondria are found in both.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-95","question":"Assertion (A): Meiosis conserves the specific chromosome number of each species across generations in sexually reproducing organisms.\nReason (R): Meiosis halves the chromosome number in the gametes, and fertilisation restores the diploid number.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. Meiosis paradoxically reduces the chromosome number by half, and this is exactly what keeps the number constant once fertilisation restores it; R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-96","question":"How many of the following statements about the prokaryotic cell envelope are correct?\n(i) In most prokaryotes it is a tightly bound three-layered structure: glycocalyx, cell wall and plasma membrane.\n(ii) The glycocalyx may be a loose slime layer in some bacteria and a thick, tough capsule in others.\n(iii) Although each layer has a distinct function, the three layers act together as a single protective unit.\n(iv) The cell wall determines the shape of the cell and stops the bacterium from bursting or collapsing.\n(v) Mycoplasma has a particularly thick cell wall.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"Statements (i) to (iv) are correct. Mycoplasma has no cell wall at all.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-97","question":"Match the stage of meiosis with its event.\nList I: (A) Metaphase I (B) Anaphase I (C) Metaphase II (D) Anaphase II\nList II: (1) Centromeres split, and sister chromatids move to opposite poles (2) Bivalents align on the equatorial plate, with microtubules from opposite poles attached to the pair of homologous chromosomes (3) Homologous chromosomes separate while sister chromatids stay together at their centromeres (4) Chromosomes align, with microtubules from opposite poles attached to the kinetochores of sister chromatids","options":["A-2, B-1, C-4, D-3","A-4, B-3, C-2, D-1","A-2, B-3, C-1, D-4","A-2, B-3, C-4, D-1"],"answer":3,"explanation":"In meiosis I the homologous pairs line up and then separate. In meiosis II single chromosomes line up with each sister kinetochore facing a pole, and the centromeres split at anaphase II.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-98","question":"From the following list, how many structures are bounded by a double membrane?\nNucleus, mitochondrion, chloroplast, lysosome, vacuole, Golgi body, endoplasmic reticulum, ribosome","options":["Exactly 2","Exactly 3","Exactly 4","Exactly 5"],"answer":1,"explanation":"The nucleus, mitochondria and chloroplasts have double membranes. Lysosomes, vacuoles, Golgi and ER have single membranes, and ribosomes have none.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-99","question":"Assertion (A): Cells of the upper layer of the epidermis, cells of the lining of the gut and blood cells are constantly replaced by mitosis.\nReason (R): Mitosis restores the nucleo-cytoplasmic ratio of a growing cell.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both statements are true and both are significances of mitosis, but cell repair (A) is not explained by the restoring of the nucleo-cytoplasmic ratio (R).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-100","question":"From the following list, how many events occur in meiosis but NOT in mitosis?\nSynapsis, crossing over, formation of chiasmata, separation of homologous chromosomes, splitting of centromeres, condensation of chromosomes, formation of a spindle","options":["Three","Four","Five","Six"],"answer":1,"explanation":"Synapsis, crossing over, chiasma formation and separation of homologues happen only in meiosis I. Centromere splitting, chromosome condensation and spindle formation happen in both divisions.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-cell-structure-division-101","question":"An organism has 2n = 12, and its cells in G₁ contain 2C DNA. A single meiocyte at anaphase I (before cytokinesis) contains how many chromosomes, counted by centromeres, and how much DNA?","options":["24 chromosomes and 4C","12 chromosomes and 2C","6 chromosomes and 2C","12 chromosomes and 4C"],"answer":3,"explanation":"In anaphase I homologues separate but centromeres do not split, so the cell still has 12 chromosomes (each with two chromatids) and the replicated 4C DNA. 24 would apply to mitotic anaphase, when centromeres split.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-102","question":"In an organism with 2n = 24, each cell at prophase II of meiosis contains:","options":["12 chromosomes, 12 chromatids and 1C DNA","24 chromosomes, 48 chromatids and 4C DNA","12 chromosomes, 24 chromatids and 2C DNA","24 chromosomes, 24 chromatids and 2C DNA"],"answer":2,"explanation":"After meiosis I each cell is haploid (12 chromosomes), but each chromosome still has two sister chromatids (24 chromatids) and no replication occurs in interkinesis, so the DNA is 2C.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-103","question":"A human somatic cell in the G₂ phase contains:","options":["46 chromosomes, 92 chromatids and 4C DNA","92 chromosomes, 92 chromatids and 4C DNA","46 chromosomes, 46 chromatids and 2C DNA","23 chromosomes, 46 chromatids and 2C DNA"],"answer":0,"explanation":"S phase doubles the DNA (2C to 4C) without changing the chromosome number, so a G₂ cell has 46 chromosomes, each with two chromatids (92).","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-104","question":"According to NCERT, which of the following needs a carrier protein to cross the plasma membrane?","options":["Neutral solutes moving down their concentration gradient","Polar molecules, unable to cross the nonpolar bilayer","Carbon dioxide diffusing out of a respiring cell","Oxygen diffusing into a cell by simple diffusion"],"answer":1,"explanation":"Neutral solutes and gases move by simple diffusion through the bilayer. Polar molecules cannot pass through its nonpolar core and require a carrier protein.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-105","question":"The Na⁺/K⁺ pump of the plasma membrane is an example of:","options":["Simple diffusion along a concentration gradient","Osmosis","Active transport using ATP against the gradient","Passive transport through a carrier protein"],"answer":2,"explanation":"The Na⁺/K⁺ pump moves ions against their concentration gradient and uses ATP, which makes it active transport.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-cell-structure-division-106","question":"Going from OUTSIDE to INSIDE between two adjacent mature plant cells, the correct order of layers of ONE cell is:","options":["Primary wall, middle lamella, secondary wall, plasma membrane","Middle lamella, secondary wall, primary wall, plasma membrane","Secondary wall, primary wall, middle lamella, plasma membrane","Middle lamella, primary wall, secondary wall, plasma membrane"],"answer":3,"explanation":"The middle lamella glues neighbouring cells together; each cell then has its primary wall, and the secondary wall is laid down later on the inner side (towards the membrane).","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-107","question":"The middle lamella that holds neighbouring plant cells together is mainly made of:","options":["Calcium pectate","Hemicellulose","Calcium carbonate","Suberin"],"answer":0,"explanation":"The middle lamella is a layer mainly of calcium pectate that glues neighbouring cells. Calcium carbonate occurs in some algal walls, not in the middle lamella.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-108","question":"Which statement about the two faces of the Golgi apparatus is correct?","options":["The cis face is concave and releases secretory vesicles to the plasma membrane","The trans face is convex and receives vesicles from the ER","The cis and trans faces are identical and work interchangeably","The cis face is convex and receives materials in vesicles from the ER"],"answer":3,"explanation":"The cis (forming) face is convex and receives ER-derived vesicles; the trans (maturing) face is concave and sends materials onward. The faces are different, though interconnected.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-109","question":"From the following list, how many organelles are part of the endomembrane system as described by NCERT?\nEndoplasmic reticulum, Golgi complex, lysosomes, vacuoles, mitochondria, chloroplasts, peroxisomes, ribosomes","options":["Three","Four","Five","Six"],"answer":1,"explanation":"The endomembrane system includes the ER, Golgi complex, lysosomes and vacuoles: four. Mitochondria, chloroplasts and peroxisomes are excluded because their functions are not coordinated with these; ribosomes are not membrane-bound.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-110","question":"Assertion (A): In plant cells, the concentration of ions in the vacuole is significantly higher than in the cytoplasm.\nReason (R): The tonoplast facilitates the transport of a number of ions and other materials against their concentration gradient into the vacuole.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because the tonoplast pumps ions into the vacuole against the gradient, their concentration there becomes much higher than in the cytoplasm. R explains A.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-111","question":"Match the plastid with what it stores or contains.\nList I: (A) Amyloplast (B) Elaioplast (C) Aleuroplast (D) Chromoplast\nList II: (1) Proteins (2) Fat-soluble carotenoid pigments (3) Starch, as in potato (4) Oils and fats","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":1,"explanation":"Amyloplasts store starch, elaioplasts oils and fats, and aleuroplasts proteins; chromoplasts contain carotenoid pigments such as carotene and xanthophylls.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-112","question":"The chloroplasts of higher plants are typically:","options":["0.2–1.0 µm wide and 1.0–4.1 µm long","15 nm wide and 20 nm long","5–10 µm long and 2–4 µm wide","50–100 µm long and 20–40 µm wide"],"answer":2,"explanation":"NCERT gives chloroplasts a length of 5–10 µm and a width of 2–4 µm. The 0.2–1.0 µm by 1.0–4.1 µm figure is for mitochondria, and 15 × 20 nm is a prokaryotic ribosome.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-113","question":"In a chloroplast, flat membranous tubules that connect the thylakoids of different grana are called:","options":["Mitochondrial cristae","Golgi cisternae","Tonoplast strands","Stroma lamellae"],"answer":3,"explanation":"Stroma lamellae connect the thylakoids of different grana. Cristae are infoldings of the inner mitochondrial membrane, and cisternae are ER or Golgi sacs.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-cell-structure-division-114","question":"How many of the following statements about chloroplasts are correct?\n(i) The inner membrane is relatively less permeable than the outer membrane.\n(ii) The stroma contains enzymes required for the synthesis of carbohydrates and proteins.\n(iii) The stroma contains small, double-stranded circular DNA molecules.\n(iv) The ribosomes of chloroplasts are 80S, like those of the cytoplasm.\n(v) Grana are stacks of thylakoids, like piles of coins.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i), (ii), (iii) and (v) are correct. Chloroplast ribosomes are 70S, smaller than the 80S cytoplasmic ribosomes, so (iv) is wrong.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-115","question":"A prokaryotic ribosome is made of a 50S and a 30S subunit, yet it is called 70S rather than 80S. This is because:","options":["S measures sedimentation, set by size and shape, so it is not additive","A 10S piece of rRNA is removed when the two subunits combine","The subunits are measured in daltons but the whole ribosome in Svedberg units","One 10S protein is released when the two subunits join together"],"answer":0,"explanation":"S (Svedberg unit) is a sedimentation coefficient, an indirect measure of density and size, not of mass, so subunit S values do not simply add up.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-116","question":"How many microtubules in all are seen in a cross-section of the axoneme of a cilium, and of a centriole, respectively?","options":["18 and 27","20 and 18","11 and 9","20 and 27"],"answer":3,"explanation":"An axoneme has 9 peripheral doublets plus 2 central microtubules: 18 + 2 = 20. A centriole has 9 peripheral triplets: 27. Forgetting the central pair gives 18.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-117","question":"Cilia and flagella of eukaryotic cells emerge from a centriole-like structure called the:","options":["Basal body","Kinetochore","Centromere","Mesosome"],"answer":0,"explanation":"Both cilia and flagella arise from a centriole-like basal body. The kinetochore and centromere are parts of chromosomes, and the mesosome is a prokaryotic membrane infolding.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-cell-structure-division-118","question":"Which of the following is NOT a function of the cytoskeleton (microtubules, microfilaments and intermediate filaments)?","options":["Mechanical support","Motility of cilia and the cell","Maintenance of cell shape","Synthesis of membrane lipids"],"answer":3,"explanation":"The cytoskeleton provides mechanical support, motility and maintenance of cell shape. Lipid synthesis is the job of the smooth ER.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-cell-structure-division-119","question":"How many of the following statements about the nucleus are correct?\n(i) The space between the two membranes of the nuclear envelope is 10 to 50 nm wide.\n(ii) The outer nuclear membrane is continuous with the ER and bears ribosomes.\n(iii) Nuclear pores are formed by fusion of the two membranes of the envelope.\n(iv) Chromatin contains DNA, histones, some non-histone proteins and RNA.\n(v) The mature erythrocytes of all mammals contain a nucleus.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i)–(iv) are correct. The mature erythrocytes of many mammals lack a nucleus, so (v) is wrong.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-120","question":"Match the type of chromosome with the position of its centromere.\nList I: (A) Metacentric (B) Sub-metacentric (C) Acrocentric (D) Telocentric\nList II: (1) At the very end (2) In the middle, giving two equal arms (3) Close to the end, giving one extremely short and one very long arm (4) Slightly away from the middle, giving one shorter and one longer arm","options":["A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3"],"answer":0,"explanation":"Metacentric: middle; sub-metacentric: slightly off-centre; acrocentric: close to the end with one very short arm; telocentric: terminal.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-121","question":"In prokaryotes, the glycocalyx may be a loose sheath or a thick, tough covering. These are called, respectively, the:","options":["Capsule and slime layer","Cell wall and capsule","Slime layer and capsule","Mesosome and cell wall"],"answer":2,"explanation":"A loose glycocalyx is a slime layer, while a thick and tough one is a capsule. Reversing them is the common trap.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-122","question":"According to NCERT, the largest isolated single cell is the:","options":["Egg of an ostrich","Human nerve cell","Human ovum","Cell of Acetabularia"],"answer":0,"explanation":"The egg of an ostrich is the largest isolated single cell. Nerve cells are among the longest cells, which is a different measure.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-cell-structure-division-123","question":"Which cells in adult animals do NOT appear to show cell division, according to NCERT?","options":["Cells of the bone marrow","Heart cells","Cells of the gut lining","Cells of the upper layer of the epidermis"],"answer":1,"explanation":"Some adult cells, such as heart cells, do not appear to divide. Epidermal, gut-lining and blood-forming cells are constantly replaced by mitosis.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-124","question":"Which statement about the occurrence of mitosis is correct according to NCERT?","options":["In plants and animals alike, mitosis occurs only in diploid somatic cells","Animals: in both haploid and diploid cells; plants: only in diploid sporophyte cells","Mitosis occurs only in haploid cells of plants and diploid cells of animals","Animals: usually diploid somatic cells only; plants: haploid and diploid cells"],"answer":3,"explanation":"In animals mitosis is usually restricted to diploid somatic cells, but plants can show mitosis in both haploid and diploid cells (e.g. the gametophyte).","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-125","question":"As daughter chromosomes move towards the poles in anaphase, they are oriented with:","options":["Their arms leading towards the pole and the centromere trailing","Their centromeres towards the pole and the arms trailing behind","Arms and centromere moving side by side towards the pole","Their telomeres attached to the spindle fibres and leading"],"answer":1,"explanation":"Spindle fibres attach at the kinetochores on the centromere, so the centromere leads towards the pole with the arms trailing behind.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-126","question":"Which event does NOT occur during telophase of mitosis?","options":["Chromosomes cluster at the poles and lose their individuality","The nuclear envelope assembles around each chromosome cluster","The nucleolus, Golgi complex and ER reform","The centromere of each chromosome splits"],"answer":3,"explanation":"Splitting of the centromere marks the start of anaphase. The other three are typical telophase events.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-127","question":"Recombination nodules appear, and X-shaped chiasmata become visible, respectively during:","options":["Zygotene and pachytene","Pachytene and diakinesis","Leptotene and zygotene","Pachytene and diplotene"],"answer":3,"explanation":"Recombination nodules, the sites of crossing over, appear at pachytene. At diplotene the synaptonemal complex dissolves and the homologues separate except at the X-shaped chiasmata.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-128","question":"Synapsis of homologous chromosomes is accompanied by the formation of the synaptonemal complex during:","options":["Leptotene","Zygotene","Diplotene","Diakinesis"],"answer":1,"explanation":"Homologous chromosomes pair (synapsis) in zygotene, and the synaptonemal complex forms then. It dissolves in diplotene.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-129","question":"At metaphase I and metaphase II of meiosis, spindle fibres from opposite poles attach respectively to the kinetochores of:","options":["Sister chromatids; homologous chromosomes","Homologous chromosomes; sister chromatids","Sister chromatids; sister chromatids","Homologous chromosomes; homologous chromosomes"],"answer":1,"explanation":"In metaphase I microtubules from opposite poles attach to the kinetochores of the two homologues of each bivalent; in metaphase II, as in mitosis, they attach to the kinetochores of sister chromatids.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-130","question":"Crossing over between non-sister chromatids of homologous chromosomes is an enzyme-mediated process. The enzyme involved is:","options":["Ligase","Helicase","Recombinase","Topoisomerase"],"answer":2,"explanation":"NCERT states that crossing over is enzyme-mediated and the enzyme involved is called recombinase.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-131","question":"How many of the following statements about meiosis II are correct?\n(i) Prophase II is usually initiated immediately after cytokinesis, before the chromosomes have fully elongated.\n(ii) The nuclear membrane disappears by the end of prophase II.\n(iii) Anaphase II begins with the simultaneous splitting of the centromere of each chromosome.\n(iv) DNA replicates during interkinesis, just before meiosis II.\n(v) Meiosis II resembles a normal mitosis.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i), (ii), (iii) and (v) are correct. Interkinesis is short-lived and has no DNA replication, so (iv) is wrong.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-132","question":"Besides plant cells, plastids are found in:","options":["Euglenoides","Amoeba","Fungi","Cyanobacteria"],"answer":0,"explanation":"NCERT states that plastids are found in all plant cells and in euglenoides. Cyanobacteria are prokaryotes with chromatophores, not plastids.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-133","question":"According to NCERT, a single human cell has a DNA thread of approximately what total length, distributed among its 46 chromosomes?","options":["Two micrometres","Two millimetres","Two metres","Two kilometres"],"answer":2,"explanation":"A single human cell has about a two-metre-long thread of DNA spread over 46 chromosomes (23 pairs), which is why packaging is needed.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-cell-structure-division-134","question":"Assertion (A): The nucleolus is not a membrane-bound structure.\nReason (R): The nucleolus is the site of active ribosomal RNA synthesis.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both are true: the nucleolus has no membrane (its content is continuous with the nucleoplasm) and it is the site of rRNA synthesis. But making rRNA does not explain the absence of a membrane.","difficulty":"very-hard","source":"NEET UG"},
];

export default questions;
